changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE SCHEMA IF NOT EXISTS "user";
CREATE TABLE IF NOT EXISTS "user".user( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, first_name TEXT, last_name TEXT, phone TEXT NOT NULL, email TEXT, password TEXT NOT NULL, auth_provider TEXT, auth_id TEXT,
is_active BOOLEAN DEFAULT TRUE, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT );
CREATE TABLE IF NOT EXISTS "user".device( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, uuid TEXT NOT NULL, os_version TEXT, os TEXT, model TEXT, brand TEXT, type TEXT, device TEXT, fcm_token TEXT, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS "user".session( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, device_id UUID NOT NULL, user_id UUID NOT NULL, timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS "user".user_company ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, user_id UUID NOT NULL, company_id UUID NOT NULL, role TEXT NOT NULL, is_main BOOLEAN DEFAULT TRUE, is_active BOOLEAN DEFAULT TRUE, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS "user".company ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL, user_id UUID NOT NULL, name TEXT NOT NULL, tin TEXT NOT NULL, type TEXT NOT NULL, deleted BOOLEAN DEFAULT FALSE, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
